const fs = require('fs');
const brief = { ts: new Date().toISOString() };

// Read empire state
try {
  brief.empire = JSON.parse(fs.readFileSync('/home/user/Orbital/nova/memory/empire_state.json', 'utf8'));
} catch { brief.empire = { status: 'unknown' }; }

// Count today's media
try {
  const files = fs.readdirSync('/home/user/Orbital/nova/media/');
  brief.media_total = files.filter(f => f.endsWith('.png') || f.endsWith('.mp4')).length;
} catch { brief.media_total = 0; }

// Read latest suggestions
try {
  const suggestions = fs.readFileSync('/home/user/Orbital/nova/memory/ceo_suggestions.jsonl', 'utf8').trim().split('\n');
  const pending = suggestions.map(s => JSON.parse(s)).filter(s => s.status === 'pending');
  brief.pending_suggestions = pending.length;
  brief.top_suggestion = pending[0] || null;
} catch { brief.pending_suggestions = 0; }

// Latest research
try {
  const research = fs.readFileSync('/home/user/Orbital/nova/memory/research.jsonl', 'utf8').trim().split('\n');
  const latest = JSON.parse(research[research.length - 1]);
  brief.latest_research = latest.topic;
} catch { brief.latest_research = 'none'; }

// Memory depth
try {
  const learnings = fs.readFileSync('/home/user/Orbital/nova/memory/learnings.jsonl', 'utf8').trim().split('\n').length;
  const decisions = fs.readFileSync('/home/user/Orbital/nova/memory/decisions.jsonl', 'utf8').trim().split('\n').length;
  brief.memory_depth = { learnings, decisions };
} catch { brief.memory_depth = { learnings: 0, decisions: 0 }; }

return [{ json: brief }];
